def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers, keyed by version tuple.

    If an explicit protocol version is provided, the dictionary will contain either zero or one items, depending on whether the protocol version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Expected protocol version to be passed in a tuple")
        if protocol_version not in cls.SUPPORTED_PROTOCOLS:
            return dict()
        return {protocol_version: cls.PROTOCOL_HANDLERS[protocol_version]}
    else:
        return {v: cls.PROTOCOL_HANDLERS[v] for v in cls.SUPPORTED_PROTOCOLS}
