    """
    Return the keys and values of this record as a dictionary, optionally including only certain values by index or key. Keys provided in the items that are not in the record will be inserted with a value of :const:`None`; indexes provided that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """

    # Get the keys from the record
    record_keys = self.keys()

    # Initialize an empty dictionary to store the results
    result_dict = {}

    # Iterate over the provided keys and include them in the result
    for key in keys:
        if isinstance(key, str):
            # If the key is a string, check if it is in the record
            if key in record_keys:
                result_dict[key] = self[key]
        elif isinstance(key, int):
            # If the key is an int, check if it is within the bounds of the record
            if key >= 0 and key < len(record_keys):
                result_dict[record_keys[key]] = self[key]
        else:
            # If the key is not a string or int, raise a TypeError
            raise TypeError("Can only accept string or int as keys")

    # Return the dictionary of results
    return result_dict

