def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point(geom.Point):
        __slots__ = tuple(fields)

        def __init__(self, srid, *args):
            super().__init__(srid, *args)
            for field, val in zip(fields, args):
                setattr(self, field, val)

            for srid, srid_type in srid_map.items():
                if srid == self.srid:
                    self._geometry_type = srid_type
                    break

        def __setattr__(self, name, value):
            if name in self.fields:
                setattr(self, name, value)
            else:
                super().__setattr__(name, value)

        @classmethod
        def from_srid(cls, srid):
            return cls(srid)

        @classmethod
        def from_geom(cls, geom):
            return cls(geom.srid, *geom.args)

        @property
        def srid(self):
            return self._geometry_type.srid

        @property
        def type(self):
            return self._geometry_type.type

        @property
        def name(self):
            return self._geometry_type.name

    return Point

