def inthread(kind=ThreadKind.SINGLETON, target=None, mapping=None, name=None):
    """
    Decorator that converts a function or a method to be executed in another
    thread.

    Prefer `functools.wraps`.

    sample usage:

    @inthread(ThreadKind.SINGLETON, "expensive operation")
    def expensive(x):
        sleep(1)
        return x

    @inthread(ThreadKind.SINGLETON, "cheap operation")
    def cheap(x):
        return x

    def sum_of_multi_tasks(a, b):
        return expensive(a + b) + cheap(a + b)

    start = clock()
    result = sum_of_multi_tasks(1000, 1000)
    stop = clock()
    assert (stop - start) < 1.0  # cheap + cheap, since expensive is in a different thread
    assert result == 2000 + 2000  # result of both tasks + results of both tasks
    """

    if not inspect.isfunction(target):
        raise RuntimeError("target is not callable")

    if kind is ThreadKind.SINGLETON:
        return FunctionThread(name, target=target).s(func)

    elif kind is ThreadKind.PARALLEL_TASKS:
        return FunctionThread.ParallelTasks(target=target, join_timeout=mapping)

    else:
        raise RuntimeError("not supported kind")

