def memoize(func):
    """
    Decorator that converts a function to memoize its result

    sample usage:

    @memoize
    def factorial(n):
        if n <= 1:
            return 1
        return n * factorial(n - 1)

    assert factorial(5) == 120
    assert factorial.cache["5"] == 120  # memoized
    assert factorial(5) == 120  # quicker
    """

    @functools.wraps(func)
    def memoized(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key not in memoized.cache:
            memoized.cache[key] = func(*args, **kwargs)
        return memoized.cache[key]

    memoized.cache = {}
    return memoized

