def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    Args:
        maxsize (int): Maximum size of the cache.
        ttl (int): Time-to-live value (in seconds) for each item in the cache.
        timer (function): Function used to generate the current time.
        typed (bool): If True, separate caches are maintained for different types of arguments.
    """

    def decorator(func):
        prefix = '.'
        if typed:
            prefix = prefix + str(type(func).__module__)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = prefix + '.' + str(args) + str(kwargs)
            now = timer()
            try:
                value, t0 = cache[key]
                if now - t0 < ttl:
                    return value
                else:
                    raise KeyError
            except KeyError:
                value = func(*args, **kwargs)
                cache[key] = (value, now)
                return value

        return wrapper

    return decorator

