def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        hits = dict()                                                     # {key: (value, hitcount)}
        misses = OrderedDict()                                            # {key: value}
        def wrapper(*args, **kwargs):
            key = (args, kwargs) if typed else args
            try:
                return hits[key][0]
            except KeyError:
                try:
                    return misses[key]
                except KeyError:
                    value = func(*args, **kwargs)
                    hits[key] = (value, 1)
                    misses[key] = value
                    if len(hits) <= maxsize:
                        hits[key][1] += 1
                    else:
                        while len(misses) >= maxsize:
                            k = misses.popitem(last=False)[0]
                            if hits[k][1] > 1:
                                hits[k][1] -= 1
                            else:
                                del hits[k]
            return wrapper
        return wrapper
    return decorator
