    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.xedges[0] or coord >= self.xedges[-1]:
        return
    if weight < 0:
        return
    bin = self.rebin(coord)
    self.values[bin] += weight

