def _infer_spec_version(inventory):
    """Infer the specification version based on the type value."""
    spec_version = None
    for item in inventory:
        if item.get("type") is not None:
            if "version" in item["type"]:
                spec_version = item["type"]["version"]
                break

    if spec_version is None:
        raise InventoryFormatException("Unable to infer the Specification version from the inventory")

    return spec_version

