def _validate_item(item, spec_version):
    """Validate an item against the Specification."""
    if "name" not in item or not isinstance(item["name"], str) or not item["name"].strip():
        raise InventoryFormatException("name field is required and must be a non-empty string")

    if spec_version in ("2.0", "2.1"):
        if "type" not in item or not isinstance(item["type"], str) or not item["type"].strip():
            raise InventoryFormatException("type field is required and must be a non-empty string")
    elif spec_version == "3.0":
        if "type" in item and not isinstance(item["type"], dict):
            raise InventoryFormatException("type field must be a dictionary (Object)")
        elif "type" not in item:
            raise InventoryFormatException("type field is required")

        if "name" not in item["type"] or not isinstance(item["type"]["name"], str) or not item["type"]["name"].strip():
            raise InventoryFormatException("type.name field is required and must be a non-empty string")
    else:
        raise InventoryFormatException(f"Unsupported Specification version: {spec_version}")

